"""1단계: 문서를 청크로 자르기 — python chunk.py docs/ > chunks.jsonl"""
import json
import re
import sys
from pathlib import Path

MAX_CHARS = 600   # 청크 최대 길이
OVERLAP = 100     # 앞 청크와 겹치는 글자 수


def split_sections(text: str):
    """마크다운 제목(#) 기준으로 큰 덩어리를 나눕니다."""
    parts = re.split(r"(?m)^(#{1,3} .+)$", text)
    title, buf = "", ""
    for p in parts:
        if re.match(r"^#{1,3} ", p):
            if buf.strip():
                yield title, buf.strip()
            title, buf = p.lstrip("# ").strip(), ""
        else:
            buf += p
    if buf.strip():
        yield title, buf.strip()


def chunk(text: str):
    """긴 덩어리는 MAX_CHARS 단위로 자르되 OVERLAP 만큼 겹칩니다."""
    start = 0
    while start < len(text):
        end = min(start + MAX_CHARS, len(text))
        yield text[start:end]
        if end == len(text):
            break
        start = end - OVERLAP


def main(folder: str):
    for path in sorted(Path(folder).glob("**/*.md")):
        text = path.read_text(encoding="utf-8")
        for title, body in split_sections(text):
            for i, piece in enumerate(chunk(body)):
                rec = {
                    "doc": path.name,
                    "section": title,
                    "part": i,
                    # 제목을 본문 앞에 붙이면 검색이 훨씬 잘 됩니다
                    "text": f"[{path.stem} > {title}] {piece}",
                }
                print(json.dumps(rec, ensure_ascii=False))


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "docs")

package study.s09;

import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Stream;

/** 1단계: 문서를 청크로 자르기 — ... -Dexec.mainClass=study.s09.Chunker -Dexec.args=docs > chunks.jsonl */
public final class Chunker {

    static final int MAX_CHARS = 600;   // 청크 최대 길이
    static final int OVERLAP = 100;     // 앞 청크와 겹치는 글자 수
    static final Pattern HEADING = Pattern.compile("^#{1,3} (.+)$");

    record Section(String title, String body) {}

    /** 마크다운 제목(#) 기준으로 큰 덩어리를 나눕니다. */
    static List<Section> splitSections(String text) {
        List<Section> out = new ArrayList<>();
        String title = "";
        StringBuilder buf = new StringBuilder();
        for (String line : text.split("\n", -1)) {
            Matcher m = HEADING.matcher(line);
            if (m.matches()) {
                if (!buf.toString().isBlank()) out.add(new Section(title, buf.toString().strip()));
                title = m.group(1).strip();
                buf.setLength(0);
            } else {
                buf.append(line).append('\n');
            }
        }
        if (!buf.toString().isBlank()) out.add(new Section(title, buf.toString().strip()));
        return out;
    }

    /** 긴 덩어리는 MAX_CHARS 단위로 자르되 OVERLAP 만큼 겹칩니다. */
    static List<String> chunk(String text) {
        List<String> out = new ArrayList<>();
        int start = 0;
        while (start < text.length()) {
            int end = Math.min(start + MAX_CHARS, text.length());
            out.add(text.substring(start, end));
            if (end == text.length()) break;
            start = end - OVERLAP;
        }
        return out;
    }

    public static void main(String[] args) throws IOException {
        Path folder = Path.of(args.length > 0 ? args[0] : "docs");
        ObjectMapper json = new ObjectMapper();
        List<Path> files;
        try (Stream<Path> s = Files.walk(folder)) {
            files = s.filter(p -> p.toString().endsWith(".md")).sorted().toList();
        }
        for (Path path : files) {
            String name = path.getFileName().toString();
            String stem = name.substring(0, name.length() - 3);
            for (Section sec : splitSections(Files.readString(path, StandardCharsets.UTF_8))) {
                List<String> pieces = chunk(sec.body());
                for (int i = 0; i < pieces.size(); i++) {
                    Map<String, Object> rec = new LinkedHashMap<>();
                    rec.put("doc", name);
                    rec.put("section", sec.title());
                    rec.put("part", i);
                    // 제목을 본문 앞에 붙이면 검색이 훨씬 잘 됩니다
                    rec.put("text", "[" + stem + " > " + sec.title() + "] " + pieces.get(i));
                    System.out.println(json.writeValueAsString(rec));
                }
            }
        }
    }
}

package study.s09;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import dev.langchain4j.data.embedding.Embedding;
import dev.langchain4j.data.segment.TextSegment;
import dev.langchain4j.model.embedding.EmbeddingModel;
import dev.langchain4j.model.embedding.onnx.OnnxEmbeddingModel;
import dev.langchain4j.model.embedding.onnx.PoolingMode;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/** 2단계: 청크를 임베딩해 저장 — ... -Dexec.mainClass=study.s09.Indexer -Dexec.args=chunks.jsonl → index-java.json */
public final class Indexer {

    @JsonIgnoreProperties(ignoreUnknown = true)
    public record Chunk(String doc, String section, int part, String text, float[] vector) {
        Chunk withVector(float[] v) {
            return new Chunk(doc, section, part, text, v);
        }
    }

    public static final Path INDEX = Path.of("index-java.json");
    static final ObjectMapper JSON = new ObjectMapper();

    /** Python 트랙과 같은 multilingual-e5-small (ONNX). 결과 벡터는 길이 1 로 정규화되어 나옵니다. */
    public static EmbeddingModel model() {
        Path dir = Path.of(System.getenv().getOrDefault("E5_DIR", "models/multilingual-e5-small"));
        return new OnnxEmbeddingModel(dir.resolve("model.onnx"), dir.resolve("tokenizer.json"), PoolingMode.MEAN);
    }

    public static List<Chunk> load() throws IOException {
        return JSON.readValue(INDEX.toFile(), new TypeReference<List<Chunk>>() {});
    }

    public static void main(String[] args) throws IOException {
        Path in = Path.of(args.length > 0 ? args[0] : "chunks.jsonl");
        List<Chunk> chunks = new ArrayList<>();
        for (String line : Files.readAllLines(in, StandardCharsets.UTF_8)) {
            if (!line.isBlank()) chunks.add(JSON.readValue(line, Chunk.class));
        }
        // e5 계열은 문서 쪽에 "passage: " 를 붙이는 것이 규칙입니다
        List<TextSegment> segments = chunks.stream().map(c -> TextSegment.from("passage: " + c.text())).toList();
        List<Embedding> vecs = model().embedAll(segments).content();
        List<Chunk> indexed = new ArrayList<>();
        for (int i = 0; i < chunks.size(); i++) indexed.add(chunks.get(i).withVector(vecs.get(i).vector()));
        JSON.writeValue(INDEX.toFile(), indexed);       // 원문·출처·벡터를 한 파일에 (청크 수천 개까지는 충분)
        System.out.println(indexed.size() + "개 청크 색인 완료 → " + INDEX);
    }
}

package study.s09;

import com.anthropic.client.AnthropicClient;
import com.anthropic.client.okhttp.AnthropicOkHttpClient;
import com.anthropic.models.messages.Message;
import com.anthropic.models.messages.MessageCreateParams;
import com.anthropic.models.messages.TextBlock;
import dev.langchain4j.model.embedding.EmbeddingModel;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

/** 3·4단계: 검색하고 근거와 함께 답하기 — ... -Dexec.mainClass=study.s09.Ask -Dexec.args="질문" */
public final class Ask {

    public static final String MODEL = System.getenv().getOrDefault("CLAUDE_MODEL", "claude-sonnet-5-5");
    static final int TOP_K = 4;

    public record Hit(double score, Indexer.Chunk chunk) {}

    public static final String SYSTEM = """
            당신은 사내 문서 Q&A 도우미입니다.
            - 반드시 <근거> 안의 내용만으로 답합니다.
            - 문장 끝에 사용한 근거 번호를 [1]처럼 붙입니다.
            - 근거로 답할 수 없으면 "문서에서 찾지 못했습니다"라고만 답합니다.""";

    public static double dot(float[] a, float[] b) {
        double s = 0;
        for (int i = 0; i < a.length; i++) s += a[i] * b[i];
        return s;
    }

    /** 정규화된 벡터이므로 내적 = 코사인 유사도. 청크 수천 개까지는 전수 비교로 충분합니다. */
    static List<Hit> search(EmbeddingModel model, List<Indexer.Chunk> index, String question, int k) {
        float[] q = model.embed("query: " + question).content().vector();
        return index.stream()
                .map(c -> new Hit(dot(q, c.vector()), c))
                .sorted(Comparator.comparingDouble(Hit::score).reversed())
                .limit(k)
                .toList();
    }

    public static void main(String[] args) throws Exception {
        String question = args.length > 0 ? String.join(" ", args) : "야간 배치가 실패하면 누구에게 연락하나요?";
        List<Hit> hits = search(Indexer.model(), Indexer.load(), question, TOP_K);

        List<String> blocks = new ArrayList<>();
        for (int n = 0; n < hits.size(); n++) {
            Indexer.Chunk c = hits.get(n).chunk();
            blocks.add("[" + (n + 1) + "] (" + c.doc() + " · " + c.section() + ")\n" + c.text());
        }
        AnthropicClient client = AnthropicOkHttpClient.fromEnv();     // ANTHROPIC_API_KEY
        Message msg = client.messages().create(MessageCreateParams.builder()
                .model(MODEL)
                .maxTokens(800)
                .system(SYSTEM)
                .addUserMessage("<근거>\n" + String.join("\n\n", blocks) + "\n</근거>\n\n질문: " + question)
                .build());
        // thinking 블록이 앞에 올 수 있어 text 블록만 골라 읽습니다
        System.out.println(msg.content().stream()
                .flatMap(b -> b.text().stream()).map(TextBlock::text).collect(Collectors.joining()));
        System.out.println("\n— 출처");
        for (int n = 0; n < hits.size(); n++) {
            Hit h = hits.get(n);
            System.out.printf("[%d] %s › %s (유사도 %.2f)%n", n + 1, h.chunk().doc(), h.chunk().section(), h.score());
        }
    }
}

"""실무형 개선: 근거가 약하면 답하지 않고, 최신 개정판만 근거로 씁니다.
ask.py 와 같은 폴더에서 실행: python policy.py "질문"
"""
import sys
from dataclasses import dataclass

from ask import LLM_MODEL, SYSTEM, client, search

MIN_SCORE = 0.78   # 이 값보다 낮으면 근거가 약하다고 봅니다 (평가셋으로 조정)


@dataclass
class Answer:
    text: str
    sources: list[dict]
    grounded: bool


def generate(question: str, picked) -> str:
    context = "\n\n".join(
        f"[{n}] ({r['doc']} · {r['section']})\n{r['text']}" for n, (_, r) in enumerate(picked, 1)
    )
    msg = client.messages.create(
        model=LLM_MODEL, max_tokens=800, system=SYSTEM,
        messages=[{"role": "user", "content": f"<근거>\n{context}\n</근거>\n\n질문: {question}"}],
    )
    return "".join(b.text for b in msg.content if b.type == "text")


def answer_with_policy(question: str) -> Answer:
    hits = search(question, k=6)
    strong = [(s, r) for s, r in hits if s >= MIN_SCORE]
    if not strong:
        return Answer(
            text="문서에서 확실한 근거를 찾지 못했습니다. 운영 당직자(내선 1234)에게 문의해 주세요.",
            sources=[], grounded=False,
        )
    # 같은 문서(doc_id)의 옛 개정판은 빼고 최신 개정판 청크만 남깁니다
    # (색인할 때 doc_id·rev_date 를 메타데이터로 함께 저장해 둔 경우)
    newest = {}
    for _, r in strong:
        key = r.get("doc_id", r["doc"])
        newest[key] = max(newest.get(key, ""), r.get("rev_date", ""))
    picked = [(s, r) for s, r in strong
              if r.get("rev_date", "") == newest[r.get("doc_id", r["doc"])]][:4]
    text = generate(question, picked)
    return Answer(text=text, grounded=True,
                  sources=[{"doc": r["doc"], "section": r["section"], "score": round(s, 2)} for s, r in picked])


if __name__ == "__main__":
    result = answer_with_policy(" ".join(sys.argv[1:]) or "재처리는 어디서부터 하나요?")
    print(result.text)
    for src in result.sources:
        print("-", src)
